# -*- coding: utf-8 -*-
# 批注数据：src/utils/messages.ts（5512 行，消息构造与归一化的中央模块）
# slug = src_utils_messages_ts
ANNOTATIONS = [
    (169, 'after', r'''文件级：消息模块的总入口——所有 create* 工厂、normalize* 归一化、reorder* 重排、各类系统/附件→可发送消息的翻译都在这一个文件里。它是把内存里的 Message 对象变成能发给 API 的 (UserMessage|AssistantMessage)[] 的装配线。'''),
    (179, 'after', r'''两个常量：MEMORY_CORRECTION_HINT 是自动记忆开启时追加的纠正提示；TOOL_REFERENCE_TURN_BOUNDARY 是工具引用占位的轮次边界标记，用来在提示词里插入干净的 Human 回合边界。'''),
    (200, 'before', r'''deriveShortMessageId：从消息 UUID 派生一个 6 位 base36 短 ID，注入到 API 侧消息里，让模型能引用消息 ID（供 snip 工具使用）。'''),
    (205, 'after', r'''实现细节：取 UUID 前 10 个 hex 字符，转成整数再转 base36 取前 6 位——确定性映射，同一 UUID 永远得到同一短 ID。'''),
    (221, 'after', r'''一组「合成消息」文本常量（INTERRUPT / CANCEL / REJECT 等）：这些是模型在权限被拒、用户中断时看到的系统级话术，本身不算用户真实输入。'''),
    (239, 'after', r'''DENIAL_WORKAROUND_GUIDANCE：权限被拒时给模型的通用应对指引——允许用其他合理工具完成，但不得恶意绕过。AUTO_REJECT_MESSAGE / DONT_ASK_REJECT_MESSAGE 是套用它的两个工厂。'''),
    (308, 'after', r'''SYNTHETIC_MODEL 与 SYNTHETIC_MESSAGES 集合：用来识别哪些是程序生成的占位消息（如中断提示），在渲染与计数时与真实内容区分。'''),
    (319, 'after', r'''isSyntheticMessage：判定一条消息是不是合成消息——靠首块文本命中 SYNTHETIC_MESSAGES 集合，且不可能是 progress/attachment/system 类型。'''),
    (339, 'after', r'''getLastAssistantMessage：用 findLast 从数组尾部往前找最后一条 assistant 消息，比 filter+last 快得多——REPL 每次渲染都调它（经 useFeedbackSurvey）。'''),
    (353, 'after', r'''hasToolCallsInLastAssistantTurn：从尾部找最后一条 assistant，看它是否含 tool_use 块，用来决定 UI 是否显示工具调用态。'''),
    (409, 'after', r'''baseCreateAssistantMessage：内部构造器，带一份完整的 usage 默认结构（含 server_tool_use、cache_creation 等嵌套字段），create* 系列都在它基础上填充。'''),
    (433, 'after', r'''createAssistantMessage：对外工厂，字符串入参会自动包成 text block；空串用 NO_CONTENT_MESSAGE 占位。'''),
    (458, 'after', r'''createAssistantAPIErrorMessage：构造 API 错误态的 assistant 消息（isApiErrorMessage=true），与正常 assistant 区分开。'''),
    (523, 'after', r'''createUserMessage：最核心的用户消息工厂，承载大量可选元数据（isMeta、compactSummary、toolUseResult、permissionMode、origin 等）——几乎所有用户侧消息都经它产出。'''),
    (543, 'after', r'''prepareUserContent：把前置输入块（precedingInputBlocks）与当前输入字符串合并；无前置块时直接返回原字符串。'''),
    (560, 'after', r'''createUserInterruptionMessage：用户中断消息，分普通中断与「为工具使用而中断」两种话术。'''),
    (571, 'after', r'''createSyntheticUserCaveatMessage：本地命令（bash/斜杠）产物的免责声明，标记为 isMeta（只有模型看到，不进转录）。'''),
    (601, 'after', r'''createModelSwitchBreadcrumbs：/model 切换时注入的面包屑三连（caveat + 命令标签 + stdout），让模型感知到对话中途的模型变更。'''),
    (620, 'after', r'''createProgressMessage：构造流式进度消息（带 toolUseID、parentToolUseID、data）。'''),
    (631, 'after', r'''createToolResultStopMessage：工具被取消时构造一个 is_error 的 tool_result 占位块。'''),
    (687, 'after', r'''extractTag：手写 HTML 标签提取，处理自闭合、带属性、嵌套与多行内容——用深度计数器确保只取最外层匹配，避免嵌套标签误截。'''),
    (720, 'after', r'''isNotEmptyMessage：判断消息是否非空；progress/attachment/system 默认非空，多块消息（块数>1）也视为非空，只有单块空文本才算空。'''),
    (728, 'after', r'''deriveUUID：从父 UUID + 内容块索引派生确定性 UUID——归一化把一条多块消息拆成多条单块消息时，靠它生成稳定的新 UUID。'''),
    (823, 'after', r'''normalizeMessages：把多块消息拆成单块（flatMap），并维护 isNewChain 标志——一旦遇到多块消息，后续所有消息都要重排 UUID，防止重复 UUID 破坏顺序。'''),
    (837, 'after', r'''isToolUseRequestMessage / isToolUseResultMessage：两个类型守卫，分别判定 assistant 含 tool_use、user 含 tool_result（注意 stop_reason 不可靠，所以直接查内容块）。'''),
    (1026, 'after', r'''reorderMessagesInUI：按工具调用把 pre-hook / tool_result / post-hook 重排到对应 tool use 周围——两遍扫描，先把消息按 toolUseID 分组，再按 工具调用→前置钩子→结果→后置钩子 顺序重建列表。'''),
    (1042, 'after', r'''isHookAttachmentMessage：内部判定哪些附件算 hook 消息（blocking_error / success / additional_context 等八种类型）。'''),
    (1096, 'after', r'''hasUnresolvedHooks：比较某工具调用的「进行中 hook 数」与「已解决 hook 数」（按 hookName 去重），前者多即视为未解决。'''),
    (1113, 'after', r'''getToolResultIDs：汇总每个 tool_use 的 result 状态（是否 is_error），输出成 { toolUseID: boolean } 字典，供配对校验用。'''),
    (1144, 'after', r'''getSiblingToolUseIDs：找同一条 assistant 消息里的兄弟 tool_use——同一 message.id 下的所有 tool_use 互为兄弟。'''),
    (1161, 'after', r'''MessageLookups 类型：渲染期为 O(1) 访问消息关系而预计算的结构（兄弟 tool_use、进度、钩子计数、result 映射、已解决/出错集合等）。'''),
    (1340, 'after', r'''buildMessageLookups：一次性构建所有消息关系索引，避免对每个消息调用 getSiblingToolUseIDs / hasUnresolvedHooks 造成的 O(n²)；还把孤立的 server_tool_use / mcp_tool_use（无对应 result）标为出错，防止 UI 一直转圈。'''),
    (1364, 'after', r'''EMPTY_LOOKUPS / EMPTY_STRING_SET：静态渲染等不需要真实查询的场景复用的空单例——用 ReadonlySet + Object.freeze 防止误改。'''),
    (1416, 'after', r'''buildSubagentLookups：为子代理/技能的进度消息构建轻量查询——只关心 tool_use 与其 result 的对应关系，并算出仍在进行中的 tool_use 集合。'''),
    (1474, 'after', r'''getToolUseIDs：收集所有 assistant 首块为 tool_use 的消息的 id，去重成集合。'''),
    (1527, 'after', r'''reorderAttachmentsForAPI：把附件向上冒泡，直到撞到 tool_result 或 assistant 消息才停——逆向扫描 + 末尾 reverse，整体 O(N) 避免 unshift 的 O(N²)。'''),
    (1533, 'after', r'''isSystemLocalCommandMessage：判定是不是 local_command 类型的系统消息（这种系统消息要当作用户消息发给模型，让它引用之前的命令输出）。'''),
    (1613, 'after', r'''stripUnavailableToolReferencesFromUserMessage：过滤指向已失联工具（如 MCP 服务断开/改名/移除）的 tool_reference 块，否则 API 报「工具引用找不到」。'''),
    (1670, 'after', r'''appendMessageTagToUserMessage：给用户消息最后一段文本块追加 [id:...] 短标签（仅改发给 API 的副本，不动存储消息），让 snip 工具能定位消息。'''),
    (1730, 'after', r'''stripToolReferenceBlocksFromUserMessage：未开启工具搜索 beta 时，剔除 tool_result 里的 tool_reference 块（该块只在 beta 下合法），否则 API 报错。'''),
    (1772, 'after', r'''stripCallerFieldFromAssistantMessage：剔除 tool_use 块里的 caller 字段——caller 只在工具搜索 beta 下合法，关掉时要显式只保留标准 API 字段。'''),
    (1817, 'after', r'''ensureSystemReminderWrap：保证附件来源的消息文本都带 <system-reminder> 包裹，使其成为后续 smoosh 的可靠判别符；已包裹的幂等不变。'''),
    (1873, 'after', r'''smooshSystemReminderSiblings：把带 <system-reminder> 前缀的文本兄弟折叠进同一条用户消息最后的 tool_result——消除「真实用户输入被当成兄弟」导致的多余 Human 边界。'''),
    (1907, 'after', r'''sanitizeErrorToolResultContent：错误 tool_result 只能含文本块（API 硬性约束），把里面的图片/文档块剥掉，防止恢复会话时每条调用都 400。'''),
    (1987, 'after', r'''relocateToolReferenceSiblings：把文本兄弟从带 tool_reference 的消息移走，避免「尾部 human 回合」异常模式教模型在工具结果后发出停止序列（见 #21049）。'''),
    (2370, 'after', r'''normalizeMessagesForAPI：发送前的总装线——先重排附件、滤掉虚拟消息，再按 system/user/assistant/attachment 分支归一化、合并相邻用户消息、多道后处理（剔除孤儿思考、滤尾部思考、滤空白、填非空、smoosh、剥离错误 content、补 [id:] 标签、校验图片大小），最后 validateImagesForAPI。'''),
    (2387, 'after', r'''mergeUserMessagesAndToolResults：合并两条用户消息并调用 hoistToolResults 把 tool_result 前置。'''),
    (2400, 'after', r'''mergeAssistantMessages：把两条 assistant 的内容块直接拼接（并发 agent 流式块按 message.id 归并）。'''),
    (2449, 'after', r'''mergeUserMessages：合并相邻用户消息；HISTORY_SNIP 开启时只有两条都是 meta 才保持 isMeta，用非 meta 那条的 uuid 保证 [id:] 标签跨调用稳定。'''),
    (2483, 'after', r'''hoistToolResults：tool_result 块必须排在前面，否则 API 报「tool result must follow tool use」——把 tool_result 抽出来前置，其余块在后。'''),
    (2515, 'after', r'''joinTextAtSeam：拼接两段内容块时在 a 的末文本块补一个换行——API 会把相邻文本块无分隔拼接，否则「2+2」+「3+3」会变「2+23+3」。'''),
    (2598, 'after', r'''smooshIntoToolResult：把内容块折叠进某个 tool_result 的 content；遇到 tool_reference 约束（不能与其他类型混）就返回 null 放弃；错误 tool_result 只收文本；返回字符串或数组合适的形状。'''),
    (2647, 'after', r'''mergeUserContentBlocks：通用合并——若前一条以 tool_result 收尾，就把后续非 tool_result 块折叠进去（universal smoosh），tool_reference 约束下退回当兄弟。'''),
    (2751, 'after', r'''normalizeContentFromAPI：修正 API 返回的块——tool_use 输入可能是字符串化 JSON（需递归解析），server_tool_use 同理；文本块原样保留以保 prompt 缓存命中。'''),
    (2757, 'after', r'''isEmptyMessageText / stripPromptXMLTags：前者判定文本是否空（剥离 XML 标签后为空或命中 NO_CONTENT_MESSAGE），后者用正则删掉 commit_analysis / context 等 XML 包裹。'''),
    (2793, 'after', r'''getToolUseID：从任意消息（attachment/assistant/user/progress/system）提取其关联的 tool_use id——是后面配对与查找的通用入口。'''),
    (2841, 'after', r'''filterUnresolvedToolUses：剔除那些所有 tool_use 块都永远没有对应 result 的 assistant 消息——直接读内容块而不调 normalizeMessages，避免生成新 UUID 污染转录。'''),
    (2859, 'after', r'''getAssistantMessageText：提取 assistant 消息里所有文本块拼接而成的字符串。'''),
    (2886, 'after', r'''getUserMessageText / textForResubmit：前者取出用户消息文本；后者专为重新提交设计——优先从 bash-input 标签、再从命令名/参数、最后剥掉 IDE 上下文标签取纯文本，并标出 bash/prompt 模式。'''),
    (2913, 'after', r'''extractTextContent / getContentText：两个文本提取工具——前者对只读结构类型按 separator 拼接文本块，后者兼容「字符串」与「块数组」两种入参。'''),
    (2949, 'before', r'''handleMessageFromStream：把 SSE 流事件翻译成 UI 回调——根据事件类型更新响应长度、追加完成消息、维护流式工具调用与思考块，并区分 tombstone / tool_use_summary / assistant 的处理。'''),
    (3134, 'after', r'''wrapInSystemReminder / wrapMessagesInSystemReminder：给内容加 <system-reminder>...</system-reminder> 包裹（字符串与块数组两种入参），供后续 smoosh 与渲染识别。'''),
    (3205, 'after', r'''PLAN_PHASE4 实验分支：四个文案变体（control / trim / cut / cap）——通过 getPewterLedgerVariant 选择，逐步压缩计划文件第四阶段的长度要求，是 A/B 实验的文案开关。'''),
    (3297, 'after', r'''getPlanModeV2Instructions：计划模式 V2 的完整提示构造——五阶段工作流（探索→设计→评审→第四阶段→ExitPlanModeV2），内联大量 ${...} 插值把 agent 数量、文件路径等填进去。'''),
    (3383, 'after', r'''getPlanModeInterviewInstructions：迭代式访谈规划提示——不强行派 Explore/Plan agent，而是让模型边读代码边问用户、把发现增量写进计划文件，循环直到完整。'''),
    (3417, 'after', r'''getPlanModeV2Sparse / SubAgentInstructions：两个分支——稀疏版只给一句提醒，子代理版面向团队里的 subagent 说明它只能读、只能编辑计划文件。'''),
    (3451, 'after', r'''getAutoModeInstructions：自动模式提示（全量版列六条行为准则 / 稀疏版一句话），核心是无须征求即可连续自主执行，但删除数据或动生产系统仍需确认。'''),
    (4286, 'after', r'''normalizeAttachmentForAPI：把几十种附件类型翻译成可发送的用户消息（巨型 switch）——目录列表、文件/图片/PDF、计划/待办提醒、MCP 资源、钩子、token 用量、压缩提醒等，几乎覆盖所有「非直接对话」的上下文注入。'''),
    (4333, 'after', r'''createToolResultMessage / createToolUseMessage：两个模拟消息工厂——把一次工具调用重建成「调用了 X 工具，输入如下」+「结果如下」的用户消息对，供附件里回放工具上下文。'''),
    (4603, 'after', r'''系统消息工厂群：createSystemMessage / createPermissionRetryMessage / createBridgeStatusMessage / createScheduledTaskFireMessage / createStopHookSummaryMessage / createTurnDurationMessage / createCompactBoundaryMessage / createMicrocompactBoundaryMessage / createSystemAPIErrorMessage 等——集中产出各类系统级（isMeta=false）消息。'''),
    (4656, 'after', r'''isCompactBoundaryMessage / findLastCompactBoundaryIndex / getMessagesAfterCompactBoundary：压缩边界的三件套——识别边界标记、从末尾往回找最后一个、取出边界之后的消息（默认还会按 HISTORY_SNIP 过滤被剪掉的消息）。'''),
    (4677, 'after', r'''shouldShowUserMessage：UI 是否显示某条用户消息——meta 消息（除 channel 来源）默认不显示，isVisibleInTranscriptOnly 在非转录模式也不显示。'''),
    (4685, 'after', r'''isThinkingMessage：判定一条消息是不是纯思考消息（所有内容块都是 thinking 或 redacted_thinking）。'''),
    (4713, 'after', r'''countToolCalls：统计某工具在消息历史里的调用次数，达到 maxCount 可提前停，用于效率优化。'''),
    (4761, 'after', r'''hasSuccessfulToolCall：从尾部找某工具最近一次的 tool_use，再找对应 tool_result，判断它是否成功（is_error 非 true）——向后搜索以提升效率。'''),
    (4828, 'after', r'''filterTrailingThinkingFromLastAssistant：API 不允许 assistant 消息以 thinking/redacted_thinking 收尾，这里把末尾连续的思考块滤掉，全删光时插 [No message content] 占位。'''),
    (4918, 'after', r'''filterWhitespaceOnlyAssistantMessages：剔除「只有空白文本块」的 assistant 消息——API 要求文本块必须含非空白字符，用户在思考块前取消会导致这种残留。'''),
    (4977, 'after', r'''ensureNonEmptyAssistantContent：保证非末条 assistant 消息内容非空（末条允许空，用于 prefill），空内容块插 NO_CONTENT_MESSAGE 占位。'''),
    (5058, 'after', r'''filterOrphanedThinkingOnlyMessages：剔除孤立的纯思考消息——流式时每块内容作为同 id 的独立消息产出，若没有另一条同 id 含非思考内容的消息来合并，就会被 API 以「思考块不可修改」拒收。'''),
    (5099, 'after', r'''stripSignatureBlocks：换凭据（如 /login）后剥离带签名的块（thinking/redacted_thinking/connector_text）——签名绑定生成它的 API key，失效后会让 API 报 400。'''),
    (5116, 'after', r'''createToolUseSummaryMessage：构造 SDK 用的工具调用摘要消息，承载摘要文本与前置 tool_use id 列表。'''),
    (5460, 'after', r'''ensureToolResultPairing：双向修复 tool_use / tool_result 配对——正向给缺 result 的 tool_use 插合成错误块，反向剥掉指向不存在 tool_use 的孤儿 result，并去重重复 result；HFI 严格模式下直接抛错而非修复（避免污染训练数据）。'''),
    (5494, 'after', r'''stripAdvisorBlocks：剔除 advisor 块——API 在无 advisor beta 头时会拒收 name 为 advisor 的 server_tool_use 块；剥空时插 [Advisor response] 占位。'''),
    (5512, 'after', r'''wrapCommandText：按消息来源（task-notification / coordinator / channel / human）包裹不同的「用户新发来消息」话术，并特别强调 channel 来源不可信、human 来源必须先响应。'''),
]
